INSERT INTO public.consultations (id, input_text, status, placeholder_response, created_at, updated_at, doctor_id, patient_session_id, clinical_representation_embedding, tenant_id, immutable_hash) VALUES ('98c212a0-f65a-4655-9bab-596a76c24cc2', 'A 10-year-old boy has progressive loss of previously acquired developmental abilities. He develops difficulty walking, dystonia, dysarthria, and intermittent vomiting. Neurologic examination demonstrates increased tone in the lower limbs and abnormal eye movements. Serum lactate is repeatedly elevated. MRI of the brain shows bilateral, relatively symmetric abnormalities involving the basal ganglia and brainstem rather than lesions confined to a single vascular territory. His older sister developed similar neurologic deterioration during early childhood and died several years later. Metabolic testing demonstrates evidence of impaired mitochondrial energy production. Genetic analysis is requested.', 'created', NULL, '2026-09-30 14:41:37.267015', '2026-09-30 14:41:38.485695', '903c2fee-d0b7-405c-b627-9bdfa3bd2f51', NULL, '[0.5477548,1.0452175,-1.8753679,-1.1040068,0.7709485,0.3180726,0.9322672,0.62374365,0.60089874,-0.5862248,-0.4434233,0.9092933,1.5601311,1.0269244,-0.78377444,-0.7518784,-1.0622512,-0.48015368,-0.94903463,0.3115931,-0.79269326,-0.040915698,-0.69837976,1.0657011,1.9179399,0.66662717,-0.8376046,0.414541,-0.22608835,0.7046044,2.095512,-0.3248885,-0.44825196,-1.0455585,-1.6799018,-0.27355245,1.3334962,0.78206,-0.20182282,0.44028422,0.9259906,-0.6226597,0.10076471,-1.0013294,-0.19130749,1.0724984,1.1708976,-0.35975888,0.78925765,-0.36149055,0.7897693,-0.15725824,0.6430242,-1.4160584,1.1380386,0.97359854,0.2693553,-0.2702485,0.188241,-0.17952524,1.8526175,0.77907884,-0.7503989,0.47623873,1.2968237,-1.0498464,-0.4828361,0.68652564,-0.3248787,-0.9185578,0.98673445,-0.89229167,0.89349693,0.74893427,-0.36615697,0.61853915,-0.20036165,0.027818864,-0.3815498,0.5253052,0.034063064,0.6139983,1.0044644,0.82229954,0.20278928,