INSERT INTO public.consultations (id, input_text, status, placeholder_response, created_at, updated_at, doctor_id, patient_session_id, clinical_representation_embedding, tenant_id, immutable_hash) VALUES ('224f99a0-5ab6-4d00-8cb9-bb922cb0e934', 'Previously healthy 27-year-old male presents with 4 days of high-grade intermittent fever associated with severe bifrontal headache, photophobia, nausea, and progressive difficulty concentrating. Over the last 18 hours, family members noticed intermittent confusion and inappropriate responses. He reports generalized myalgia and reduced appetite. No witnessed seizures. No focal limb weakness or sensory loss.
INSERT INTO public.consultations (id, input_text, status, placeholder_response, created_at, updated_at, doctor_id, patient_session_id, clinical_representation_embedding, tenant_id, immutable_hash) VALUES ('22ee0ebf-d6a4-4c9d-9de0-7fcf58e6b9e5', '
INSERT INTO public.consultations (id, input_text, status, placeholder_response, created_at, updated_at, doctor_id, patient_session_id, clinical_representation_embedding, tenant_id, immutable_hash) VALUES ('ae003e5d-0cb7-41ac-a3a2-effee848a7a4', 'A 7-year-old child has poor growth and low body weight compared with other children of the same age. The child has very little body fat, thin skin, hair loss, a small face, and stiffness in the joints. The child appears much older than their actual age. They have normal intelligence but have difficulty gaining weight and height. The differential diagnosis should consider nutritional disorders, endocrine diseases, metabolic disorders, and rare genetic conditions. Further evaluation would include a detailed medical history, physical examination, growth measurements, blood tests, and genetic testing.
INSERT INTO public.consultations (id, input_text, status, placeholder_response, created_at, updated_at, doctor_id, patient_session_id, clinical_representation_embedding, tenant_id, immutable_hash) VALUES ('746bc335-af23-4516-93b4-fe350651f645', 'Patient is a 48 yo male presenting with acute crushing chest pain, diaphoresis, left arm radiation, BP 140/85, HR 92. Denies trauma or cough.', 'created', NULL, '2026-10-07 14:59:05.079628', '2026-10-07 14:59:05.079628', 'f2605812-fa00-4be6-8067-3f0abfb53dd7', NULL, NULL, '438b3752-77b2-4b64-8a07-e5eeb8a8ccf5', NULL);
