INSERT INTO public.consultations (id, input_text, status, placeholder_response, created_at, updated_at, doctor_id, patient_session_id, clinical_representation_embedding, tenant_id, immutable_hash) VALUES ('796d91f9-5494-4f25-859c-3f60117844c3', 'child appears healthy at birth but gradually develops severe muscle weakness during infancy. The child has difficulty sitting, standing, or walking and may have trouble swallowing or breathing. The muscles close to the body, such as those around the hips and shoulders, are particularly weak. Reflexes may be reduced, while sensation and intelligence are generally preserved. Genetic testing and specialized muscle or nerve investigations can help confirm the diagnosis.', 'created', NULL, '2026-10-08 04:24:19.854964', '2026-10-08 04:26:37.67696', '903c2fee-d0b7-405c-b627-9bdfa3bd2f51', NULL, '[0.6818794,0.71416897,-2.6301942,-0.8154588,0.74331963,0.7400522,0.54080814,-0.03525727,1.0440161,-1.1752378,-0.7351151,0.44955656,1.340697,0.8097575,-0.6403964,-0.64245594,-0.18998869,-1.6929227,0.4902202,1.0116296,-0.83581924,0.5959686,-0.96803904,1.5244782,1.8687993,1.0150232,-1.013087,1.0794754,-0.50851107,0.15396523,1.7689939,-0.9680472,0.68486565,-1.3498064,-1.5096772,-0.16430835,1.6427875,0.8036704,-0.3633783,-0.105280295,0.4183308,-0.93043077,0.17629707,-1.0595073,-0.3578885,0.095290214,1.0349559,0.21456489,0.8528091,-0.6490114,0.31564036,-0.959195,0.4314158,-0.5034603,1.6421812,0.24752526,0.48494518,0.18397991,0.27101177,-1.0472553,1.8449042,0.1985263,-1.2661533,0.9876814,1.0563508,-0.5926863,-0.61288804,0.9765561,0.7506542,-0.18074384,1.29532,-1.0462382,0.5592952,0.6252934,-0.46776718,0.47398427,-0.30013862,0.1675124,-1.2072613,1.0398927,0.8222925,0.68695885,0.50080067,0.24375571,1.4942945,0.23948094,-0.3383079,0.44750842,0.0090697855,2.1582148,0.22854665,1.2795953,-0.12090758,-0.4299741,-0.33340466,0.565614,0.42015088,-0.31817487,-0.25833276,-0.5548025,-0.7331284,-0.6487087,-0.8099426,-0.58200765,0.026163734,0.679191,0.5105067,-0