INSERT INTO public.post_bookmarks (id, created_at, updated_at, post_id, doctor_id, folder_name) VALUES ('e249b11a-a1f0-46e9-8d3f-3061958b0d12', '2026-09-27 06:23:10.61634', '2026-09-27 06:23:10.61634', '95aa1af5-bcf1-44ba-ba5a-1ac1813a4a37', '903c2fee-d0b7-405c-b627-9bdfa3bd2f51', 'General');
INSERT INTO public.post_comments (id, created_at, updated_at, post_id, author_id, content) VALUES ('99e2733e-a2b8-407c-9701-d83a3b1974de', '2026-09-27 05:23:10.665064', '2026-09-27 06:23:10.61634', 'e4c8a60b-2e64-484d-b47d-e5509f6a9231', 'dd7d2ebf-797c-4f88-adcd-aa8923f075f3', 'Crucial catch on the pain-free ECG. We frequently see junior residents miss the biphasic T waves when the patient says ''the pain is totally gone now''.');
INSERT INTO public.post_comments (id, created_at, updated_at, post_id, author_id, content) VALUES ('b3bc5aab-e4d0-44a3-aced-2d31570e4ac3', '2026-09-27 05:23:10.665064', '2026-09-27 06:23:10.61634', 'e4c8a60b-2e64-484d-b47d-e5509f6a9231', '7fa23e69-2803-4d8a-8301-d8cb9dda4b3a', 'Classic pseudo-normalization danger if stress tested. Superb outcome with rapid catheterization.');
INSERT INTO public.post_comments (id, created_at, updated_at, post_id, author_id, content) VALUES ('5260af3a-28f5-4183-b134-eea8d539b456', '2026-09-27 03:23:10.712571', '2026-09-27 06:23:10.61634', '9acd08e7-62ae-4faf-8114-95d541f6bb03', 'ec0331a4-43ea-4bcf-93ef-fc38a06aa25b', 'Extreme delta brush is practically diagnostic when combined with orofacial dyskinesias. Excellent decision on prompt tumor resection.');
INSERT INTO public.post_comments (id, created_at, updated_at, post_id, author_id, content) VALUES ('beb6b4cf-4d18-45ba-9d31-49693485307f', '2026-09-27 03:23:10.712571', '2026-09-27 06:23:10.61634', '9acd08e7-62ae-4faf-8114-95d541f6bb03', 'cb6b5947-1bbf-4011-bc52-b60479b10993', 'How was the autonomic instability managed hemodynamically during the ICU stay? Did you require Clonidine or Dexmedetomidine?');
INSERT INTO public.post_comments (id, created_at, updated_at, post_id, author_id, content) VALUES ('563969b0-2b20-4b40-a569-20f7e2f3a689', '2026-09-27 01:23:10.712571', '2026-09-27 06:23:10.61634', 'b8d2d2a9-9f44-433f-ad36-c1a5a2765e36', 'cb6b5947-1bbf-4011-bc52-b60479b10993', 'Early IVIG within the 10-day window is life-saving to prevent aneurysm thrombosis. Great echo surveillance protocol.');
INSERT INTO public.post_comments (id, created_at, updated_at, post_id, author_id, content) VALUES ('8a35643c-690b-4e19-be71-921d6c91c29a', '2026-09-27 01:23:10.712571', '2026-09-27 06:23:10.61634', 'b8d2d2a9-9f44-433f-ad36-c1a5a2765e36', '4fb80e8c-fc90-48e9-9da9-c1caa606d4ae', 'The palm induration and periungual peeling are such high-yield clinical dermatologic signs in fever of unknown origin in toddlers.');
INSERT INTO public.post_comments (id, created_at, updated_at, post_id, author_id, content) VALUES ('d66d6202-089c-4548-bac0-1f9e71b9621b', '2026-09-26 23:23:10.728441', '2026-09-27 06:23:10.61634', '82df937f-b20d-4d76-939e-140d47d4725e', 'ec0331a4-43ea-4bcf-93ef-fc38a06aa25b', 'With ferritin > 40k and cytopenias, prompt dexamethasone is imperative. In adult viral-triggered HLH, Anakinra (IL-1 blockade) has shown lower myelosuppression risk than etoposide.');
INSERT INTO public.post_comments (id, created_at, updated_at, post_id, author_id, content) VALUES ('111cf88a-e8d5-404a-8a80-f0ab2de4bc80', '2026-09-26 23:23:10.728441', '2026-09-27 06:23:10.61634', '82df937f-b20d-4d76-939e-140d47d4725e', 'cb6b5947-1bbf-4011-bc52-b60479b10993', 'Watch closely for myocardial depression and secondary dengue myocarditis in this hyperferritinemic storm.');
INSERT INTO public.post_comments (id, created_at, updated_at, post_id, author_id, content) VALUES ('3f639f91-d208-4634-9ca7-a6483fb7e57a', '2026-09-26 21:23:10.728441', '2026-09-27 06:23:10.61634', '95aa1af5-bcf1-44ba-ba5a-1ac1813a4a37', 'dd7d2ebf-797c-4f88-adcd-aa8923f075f3', 'Crucial reminder for primary care clinicians to screen HLA-B*58:01 prior to allopurinol initiation in high-risk ancestral populations.');
INSERT INTO public.post_comments (id, created_at, updated_at, post_id, author_id, content) VALUES ('c4fd2f8f-1992-4776-b4a2-6e54046df519', '2026-09-26 21:23:10.728441', '2026-09-27 06:23:10.61634', '95aa1af5-bcf1-44ba-ba5a-1ac1813a4a37', '7fa23e69-2803-4d8a-8301-d8cb9dda4b3a', 'Early cyclosporine has significantly improved SCORTEN-adjusted survival in multicenter registries.');
INSERT INTO public.post_comments (id, created_at, updated_at, post_id, author_id, content) VALUES ('28649cbc-f13b-426e-9e91-74dfa8c81384', '2026-09-27 12:28:44.613558', '2026-09-27 12:28:44.613558', '82df937f-b20d-4d76-939e-140d47d4725e', 'b9f14389-37bf-4d51-91ac-3fd6df18ffab', 'Verified peer consensus: hemodynamic stabilization achieved.');
