INSERT INTO public.post_treatment_suggestions (post_id, author_id, drug_or_intervention, dosage_and_route, clinical_rationale, evidence_grade, endorsements_count, is_adopted, id, created_at, updated_at) VALUES ('82df937f-b20d-4d76-939e-140d47d4725e', '948e6dcd-b5c3-4fea-9e5a-6b7d0a5d6ab9', 'Piperacillin-Tazobactam + Vancomycin Protocol with TDM', '4.5g IV q6h extended infusion (over 4h) + Vancomycin 15-20 mg/kg q8h', 'Given hemodynamic instability and suspected septic source with high local MRSA prevalence, initiate broad-spectrum coverage covering Pseudomonas and MRSA within 1 hour per Surviving Sepsis Campaign guidelines. De-escalate based on 48h blood culture susceptibility.', 'Grade 1A (Surviving Sepsis Guidelines)', 8, true, '9f81fa5a-d73d-484f-b80a-fc089649ef6f', '2026-10-02 13:54:09.600055', '2026-10-02 13:54:09.600055');
